def is_neq_number(x: int) -> bool:
    s = str(x)
    for i in range(len(s) - 1):
        if s[i] == s[i + 1]:
            return False
    return True

def count_neq_numbers(maxi: int) -> int:
    count = 0
    for i in range(1, maxi + 1):
        if is_neq_number(i):
            count += 1
    return count

